custom_css:
/* 云端邮局 · reference reconstruction, modular external textures and ornaments. */

:root{--pr-ink:#365f8b;--pr-base:#eaf4ff;}
#sheld{background:var(--pr-base)!important;box-shadow:none!important;backdrop-filter:none!important;}
#chat{padding:0!important;gap:0!important;container-type:inline-size;background:var(--pr-base) url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/postal/surface.webp') center top/100% auto repeat-y!important;}
#chat .mes{position:relative;isolation:isolate;box-sizing:border-box;display:grid!important;grid-template-columns:minmax(0,48%) minmax(0,1fr);column-gap:12px;row-gap:16px;align-items:center!important;width:100%!important;max-width:720px!important;min-width:0!important;margin:0 auto 24px!important;padding:24px 20px 80px!important;border:0!important;border-radius:0!important;background:none!important;box-shadow:none!important;color:var(--pr-ink)!important;backdrop-filter:none!important;}
#chat .mes>.mes_block{display:contents!important;}
#chat .mes::before,#chat .mes::after,#chat .mes>.mes_block::before,#chat .mes>.mes_block::after{content:'';position:absolute;pointer-events:none;background-repeat:no-repeat;background-size:contain;z-index:-1;}
#chat .mes .mesAvatarWrapper{grid-column:1;grid-row:1;position:relative!important;display:flex!important;flex-wrap:wrap;justify-content:space-around;align-items:center;align-content:start;gap:12px 2px;width:auto!important;max-width:100%!important;min-width:0!important;margin:0!important;padding:0!important;}
#chat .mes .avatar{box-sizing:border-box;position:relative;flex:0 0 100%;width:100%!important;max-width:none!important;height:auto!important;aspect-ratio:1;margin:0!important;padding:0!important;border:0!important;box-shadow:none!important;background:none!important;}
#chat .mes .avatar img{width:100%!important;height:100%!important;object-fit:cover!important;object-position:center 35%;border-radius:inherit!important;box-shadow:none!important;}
#chat .mes .mesIDDisplay,#chat .mes .mes_timer,#chat .mes .tokenCounterDisplay{position:static!important;width:auto!important;margin:0!important;padding:0!important;line-height:1.4!important;font-size:9px!important;color:var(--pr-ink)!important;opacity:.75;}
#chat .mes .ch_name{grid-column:2;grid-row:1;align-self:center;position:relative;display:flex!important;flex-direction:column!important;justify-content:center!important;align-items:stretch!important;gap:12px;width:100%!important;min-width:0!important;margin:0!important;padding:0!important;background:none!important;}
#chat .mes .ch_name>.flex1{display:flex!important;flex:none!important;justify-content:center;align-items:center;min-width:0;text-align:center;}
#chat .mes .name_text{display:block;max-width:100%;font-size:21px!important;line-height:1.4;font-weight:400;color:var(--pr-ink)!important;overflow-wrap:anywhere;}
#chat .mes .timestamp{font-size:9px;}
#chat .mes .mes_buttons{position:relative!important;display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:2px!important;width:100%!important;max-width:100%!important;min-width:0!important;margin:0!important;padding:4px 0!important;float:none!important;opacity:1!important;}
#chat .mes .mes_button{box-sizing:border-box;flex:0 0 auto;min-width:20px;min-height:26px;padding:2px!important;color:var(--pr-ink)!important;filter:none!important;text-shadow:none!important;}
#chat .mes .extraMesButtons{flex-wrap:wrap;justify-content:center;gap:4px;max-width:100%;flex-basis:100%;}
#chat .mes .mes_text{grid-column:1/-1;position:relative;box-sizing:border-box;width:100%!important;min-width:0!important;margin:0!important;padding:24px 15px 35px!important;min-height:200px;line-height:1.9!important;color:var(--pr-ink)!important;overflow-wrap:anywhere;}
#chat .mes .mes_text p{margin:.4em 0 .9em;}
#chat .mes .mes_text img,#chat .mes .mes_text video{max-width:100%;height:auto;}
#chat .mes .mes_text pre{max-width:100%;overflow-x:auto;}
#chat .mes .mes_text table{display:block;max-width:100%;overflow-x:auto;}
#chat .mes>.for_checkbox{position:absolute;left:4px;top:4px;}
#chat .mes>.swipe_left{position:absolute;left:10px;bottom:14px;z-index:3;}
#chat .mes>.swipe_right{position:absolute;right:10px;bottom:14px;z-index:3;}
#chat .mes .swipes-counter{color:var(--pr-ink);}
#top-bar{background:var(--pr-base) url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/postal/surface.webp') center top/100% auto!important;box-shadow:none!important;border:0!important;}
#top-settings-holder{gap:0!important;}
#top-settings-holder>.drawer{min-width:0!important;flex:1 1 0;}
#top-settings-holder .drawer-toggle{display:flex;align-items:center;justify-content:center;min-height:38px;}
#top-settings-holder .drawer-icon{color:var(--pr-ink)!important;filter:none!important;opacity:1!important;font-size:22px!important;}
#send_form{position:relative;isolation:isolate;box-sizing:border-box;gap:8px!important;min-height:64px;padding:12px 18px!important;border:0!important;box-shadow:none!important;border-radius:0!important;background:var(--pr-base) url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/postal/surface.webp') center bottom/100% auto!important;}
#send_form::before{content:'';position:absolute;inset:5px;z-index:-1;pointer-events:none;background:rgba(255,255,255,.85);border-radius:20px;}
#send_textarea{background:transparent!important;color:var(--pr-ink)!important;border:0!important;box-shadow:none!important;min-height:36px;}
#send_textarea::placeholder{color:var(--pr-ink);opacity:.7;}
#send_form :is(i,.fa-solid,.fa-regular){color:var(--pr-ink)!important;filter:none!important;}
@media(min-width:700px){#chat .mes .name_text{font-size:25px!important;}#chat .mes .mes_text{font-size:18px;}}

#chat .mes{width:calc(100% - 24px)!important;grid-template-columns:minmax(0,1fr) minmax(0,29%);margin-top:120px!important;padding:24px 22px 58px!important;gap:8px 12px;}
#chat .mes::before{inset:0;background:#fff url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/postal/paper-grain.webp') center/400px auto repeat;box-shadow:2px 2px 2px #bdd1e233;z-index:-2;}
#chat .mes>.mes_block::before{left:-4px;right:-4px;top:clamp(-100px,-13.5vw,-46px);height:130px;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/postal/letter-top.webp') center top/100% auto no-repeat;z-index:-3;}
#chat .mes::after{left:-6px;right:-6px;bottom:-12px;height:135px;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/postal/letter-bottom.webp') center bottom/100% auto no-repeat;z-index:0;}
#chat .mes .mesAvatarWrapper{grid-column:2;grid-row:1;transform:rotate(5deg);gap:10px 2px;}
#chat .mes .avatar{aspect-ratio:.83;background:#fff!important;border:7px solid #fff!important;border-radius:0!important;mask:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/postal/stamp-mask.svg') center/100% 100% no-repeat;}
#chat .mes .avatar::after{content:'';position:absolute;inset:-7px;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/postal/stamp-border.svg') center/100% 100% no-repeat;pointer-events:none;}
#chat .mes .ch_name{position:static;grid-column:1;grid-row:1;align-self:center;padding:0 0 15px!important;}
#chat .mes .ch_name>.flex1{position:relative;justify-content:flex-start;text-align:left;padding-bottom:22px;}
#chat .mes .name_text{font-size:23px!important;transform:rotate(-4deg);}
#chat .mes .ch_name>.flex1::after{content:'';position:absolute;left:0;bottom:-10px;width:100%;height:32px;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/postal/postmark.svg') left center/contain no-repeat;pointer-events:none;}
#chat .mes .mes_buttons{position:absolute!important;right:-2px;top:clamp(155px,41vw,270px);width:37px!important;max-width:37px!important;flex-direction:column!important;gap:4px!important;z-index:3;}
#chat .mes .mes_button{width:34px;height:30px;background-position:center!important;background-size:contain!important;background-repeat:no-repeat!important;border:0;}
#chat .mes .mes_text{min-height:180px;padding:14px 30px 25px 10px!important;}
#send_form{padding:22px 20px 15px!important;}
#send_form::before{inset:-12px 0 0;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/postal/composer.webp') center/100% auto no-repeat;border-radius:0;}

#top-settings-holder>.drawer:nth-child(1) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/postal/icon-1.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(1) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(2) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/postal/icon-2.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(2) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(3) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/postal/icon-3.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(3) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(4) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/postal/icon-4.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(4) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(5) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/postal/icon-1.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(5) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(6) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/postal/icon-2.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(6) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(7) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/postal/icon-3.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(7) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(8) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/postal/icon-4.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(8) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(9) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/postal/icon-1.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(9) .drawer-icon::before{opacity:0!important;}
#chat .mes .mes_button:nth-child(2){background-image:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/postal/icon-1.webp');font-size:0!important;}#chat .mes .mes_button:nth-child(2)::before{opacity:0;}
#chat .mes .mes_button:nth-child(3){background-image:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/postal/icon-2.webp');font-size:0!important;}#chat .mes .mes_button:nth-child(3)::before{opacity:0;}
#chat .mes .mes_button:nth-child(4){background-image:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/postal/icon-3.webp');font-size:0!important;}#chat .mes .mes_button:nth-child(4)::before{opacity:0;}
#chat .mes .mes_button:nth-child(5){background-image:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/postal/icon-4.webp');font-size:0!important;}#chat .mes .mes_button:nth-child(5)::before{opacity:0;}
#chat .mes .mes_button:nth-child(6){background-image:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/postal/icon-1.webp');font-size:0!important;}#chat .mes .mes_button:nth-child(6)::before{opacity:0;}
#send_but{background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/postal/icon-2.webp') center/contain no-repeat!important;font-size:0!important;}#send_but::before{opacity:0;}
#chat .mes .mes_buttons .extraMesButtons{position:absolute;right:40px;top:0;width:76px;max-width:76px;flex-basis:auto;padding:6px;background:rgba(248,252,255,.98);border:1px solid #c5d9e7;border-radius:12px;z-index:5;}
#chat{background-position:center calc(-50vw)!important;}#chat .mes>.mes_block::after{right:8px;top:-115px;width:120px;height:75px;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/postal/accent.webp') center/contain no-repeat;z-index:-1;}
#chat .mes .mesAvatarWrapper :is(.mesIDDisplay,.mes_timer,.tokenCounterDisplay){position:absolute!important;bottom:-16px;font-size:7px!important;}#chat .mes .mesAvatarWrapper .mesIDDisplay{left:0;}#chat .mes .mesAvatarWrapper .mes_timer{left:28%;}#chat .mes .mesAvatarWrapper .tokenCounterDisplay{right:0;}
html,body,body *{scrollbar-width:none!important;scrollbar-gutter:auto!important;}
body::-webkit-scrollbar,body *::-webkit-scrollbar,html::-webkit-scrollbar{width:0!important;height:0!important;display:none!important;}
#chat{padding-inline:0!important;border-inline:0!important;box-sizing:border-box!important;background-attachment:scroll!important;}
#chat .mes .mes_buttons{overflow:visible!important;max-height:none!important;}

#chat .mes>:not(.mesAvatarWrapper):not(.mes_block):not(.for_checkbox):not(.swipe_left):not(.swipe_right),
#chat .mes>.mes_block>:not(.ch_name):not(.mes_text){grid-column:1/-1!important;min-width:0;max-width:100%;box-sizing:border-box;}
#chat .mes .mes_text{padding-left:8px!important;padding-right:8px!important;}

#chat .mes{padding-left:12px!important;padding-right:12px!important;}#chat .mes .mes_text{padding-right:30px!important;}
#chat .mes .ch_name>.flex1{padding-bottom:58px!important;}
#chat .mes .ch_name>.flex1::after{left:0;bottom:0;width:100%;height:50px;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/postal/cloud-ornament.webp') center/contain no-repeat!important;}
#chat .mes .mes_buttons{display:flex!important;flex-direction:column!important;align-items:center!important;justify-content:flex-start!important;gap:8px!important;padding:0!important;box-sizing:border-box;right:0!important;width:36px!important;min-width:36px!important;}
#chat .mes .mes_buttons>:not(.extraMesButtons),#chat .mes .mes_buttons .mes_button{box-sizing:border-box!important;float:none!important;position:relative!important;left:auto!important;right:auto!important;transform:none!important;flex:0 0 32px!important;width:32px!important;min-width:32px!important;max-width:32px!important;height:32px!important;min-height:32px!important;margin:0!important;padding:0!important;text-align:center!important;line-height:32px!important;background-position:center!important;background-size:contain!important;}
#chat .mes .mes_buttons>:not(.extraMesButtons)>img{max-width:28px!important;max-height:28px!important;object-fit:contain!important;vertical-align:middle!important;}
#send_form :is(#options_button,#extensionsMenuButton){flex:0 0 32px!important;width:32px!important;height:36px!important;min-width:32px!important;font-size:0!important;background-position:center!important;background-size:contain!important;background-repeat:no-repeat!important;}
#send_form #options_button{background-image:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/postal/mail-menu.webp')!important;}
#send_form #extensionsMenuButton{background-image:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/postal/quill-tools.webp')!important;}
#send_form :is(#options_button,#extensionsMenuButton)::before{opacity:0!important;}
